import React, { useState } from 'react';
import styled from 'styled-components';
import ResultComponent from './ResultComponent';
import { apiGetSamplesByExperimentId } from '../service/sample';

const PopUpContainer = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.5);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1000;
`;

const PopUpForm = styled.div`
  background-color: white;
  padding: 20px;
  border-radius: 8px;
  width: 90%;
  max-height: 80%;
  overflow-y: auto;
  position: relative;
`;

const CloseButton = styled.button`
  position: absolute;
  top: 10px;
  right: 10px;
  background-color: transparent;
  border: none;
  font-size: 24px;
  cursor: pointer;
  color: #888;

  &:hover {
    color: #000;
  }
`;

const Title = styled.h3`
  text-align: center;
  font-size: 30px;
  margin-bottom: 20px;
`;

const Table = styled.table`
  width: 90%;
  border-collapse: collapse;
  margin: 0 auto;
`;

const TableHeader = styled.th`
  background-color: #f4f4f4;
  padding: 10px;
  text-align: left;
  font-weight: bold;
`;

const TableData = styled.td`
  padding: 10px;
  text-align: left;
  border-bottom: 1px solid #ddd;
`;

const TableRow = styled.tr`
  &:hover {
    background-color: #f9f9f9;
  }
`;

const Icon = styled.span`
  cursor: pointer;
  margin-left: 20px;
  color: ${(props) => props.color || '#007bff'};
  font-size: 30px;

  &:hover {
    color: ${(props) => props.color ? props.color : '#0056b3'};
  }
`;

const ExperimentInfo = ({ showModal, closeModal, experiments }) => {
  if (!showModal) return null;

  const [fastaInfo, setFastaInfo] = useState({
    name: "Sample1",
    header: ">Sample1_header",
    length: 12345,
    createdAt: "2025-04-01T14:30:00Z"
  });

  const [virulenceInfo, setVirulenceInfo] = useState([]);

  const [amrInfo, setAmrInfo] = useState([]);
  const [showResultAll, setShowResultAll] = useState(false)
  const [showResult, setShowResult] = useState(
    experiments.reduce((acc, _, index) => ({ ...acc, [index]: false }), {})
  );
  const handleGetResult = (index) => {
    setShowResultAll(!showResultAll);
    setShowResult((prevState) => ({
      ...prevState,
      [index]: !prevState[index] 
    }));
  };

  return (
    <PopUpContainer>
      <PopUpForm>
        <CloseButton onClick={closeModal}>×</CloseButton>
        <Title>Thông Tin Thí Nghiệm</Title>
        <Table>
          <thead>
            <tr>
              <TableHeader>STT</TableHeader>
              <TableHeader>Tên Mẫu Thí Nghiệm</TableHeader>
              <TableHeader>Tên Tệp FASTA</TableHeader>
              <TableHeader>Chi Tiết</TableHeader>
            </tr>
          </thead>
          <tbody>
            {experiments.map((experiment, index) => (
              <TableRow key={index}>
                <TableData>{index + 1}</TableData>
                <TableData>{experiment.name}</TableData>
                <TableData>
                  {experiment.fastaFile}
                  <Icon onClick={() => alert('Tải xuống tệp FASTA')}>⤓</Icon>
                </TableData>
                <TableData>
                  <Icon onClick={() => handleGetResult(index)}>{showResult[index] ? '🧐' : '🔍'}</Icon>
                </TableData>
              </TableRow>
            ))}
          </tbody>
        </Table>
        {showResultAll && <ResultComponent fastaInfo={fastaInfo} virulenceInfo={virulenceInfo} amrInfo={amrInfo} />}
      </PopUpForm>
    </PopUpContainer>
  );
};

export default ExperimentInfo;
